#include <initializer_list>
#include <iostream>

class Widget {
public:
  Widget() {
    // Default constructor
    std::cout << "Default ctor\n";
  }
  Widget(std::initializer_list<int> il) {
    // Initializer list constructor
    std::cout << "std::initializer_list ctor with " << il.size() << " elements\n";
  }
};

// ... in some function
Widget w1;       // Calls default constructor
Widget w2{};     // Also calls default constructor (value initialization)
Widget w3({});    // Calls std::initializer_list ctor with an empty list
Widget w4{{}};   // Also calls std::initializer_list ctor with an empty list
